  register('dictionary-delete', 'Удалить запись справочника?', 'Справочники', () => `<p>Проверьте выбранную запись перед удалением. Она используется при настройке заявок.</p><div class="actions">${B('Удалить', 'toast:Запись удалена в макете', 'danger')}${B('Отмена', 'close')}</div>`, {kind: 'dialog'});
  register('device-models', 'Модели устройств', 'Справочники', () => card('Модели приборов учёта', `${tableTools('Название модели')}${R.table(['Модель', 'МПИ, лет', 'Тарифность', 'Фазность', 'Тип', ''], [[link('Меркурий 230 ART', 'device-model-edit'), '10', '3', '3', 'Счётчик электроэнергии', B('Изменить', 'modal:device-model-edit', 'subtle')], [link('Энергомера CE 101', 'device-model-edit'), '16', '1', '1', 'Счётчик электроэнергии', B('Изменить', 'modal:device-model-edit', 'subtle')], [link('НЕВА МТ 124', 'device-model-edit'), '16', '2', '1', 'Счётчик электроэнергии', B('Изменить', 'modal:device-model-edit', 'subtle')]])}${pages}`), {tabs: dictionaryTabs, primary: ['Добавить модель', 'modal:device-model-create']});
  const modelFields = (edit) => `${field('Название модели', edit ? 'Меркурий 230 ART' : '', 'text', {required: true, wide: true})}${field('МПИ в годах', edit ? '10' : '', 'number', {required: true})}${field('Тарифность', edit ? '3' : '', 'number', {required: true})}${field('Фазность', edit ? '3' : '', 'number', {required: true})}${select('Тип устройства', ['Счётчик электроэнергии', 'Модем', 'Контроллер'], 'Счётчик электроэнергии', {required: true})}`;
