  register('devices', 'Устройства', 'Справочники', () => card('Реестр оборудования', `${tableTools('Заводской номер, модель или оператор', select('Критерий поиска', ['Заводской номер', 'Мобильный оператор', 'Название модели', 'Год производства'], 'Заводской номер'))}${R.table(['Заводской номер', 'Модель', 'Год', 'Оператор', 'Пломба', ''], [[link('10284756', 'device-edit'), 'Меркурий 230 ART', '2025', 'МТС', 'П-124887', B('Открыть', 'modal:device-edit', 'subtle')], [link('10284757', 'device-edit'), 'Меркурий 230 ART', '2025', 'МегаФон', 'П-124888', B('Открыть', 'modal:device-edit', 'subtle')], [link('30661204', 'device-edit'), 'Энергомера CE 101', '2024', '—', 'П-124889', B('Открыть', 'modal:device-edit', 'subtle')]])}${pages}`), {tabs: dictionaryTabs, primary: ['Импорт устройств', 'go:import-devices']});
  register('device-edit', 'Устройство №10284756', 'Справочники', () => form(`${field('Модель', 'Меркурий 230 ART', 'text', {readonly: true, wide: true})}${field('Мобильный оператор', 'МТС', 'text', {required: true})}${field('Год производства', '2025', 'number', {required: true})}${field('Заводской номер', '10284756', 'text', {required: true})}${field('IP-адрес', '10.20.1.25')}${field('Номер пломбы', 'П-124887', 'text', {required: true})}${field('SIM ICC', '8970101012345678901')}<div class="wide"><h3>Показания прибора</h3></div>${field('T1', '12458.20', 'number', {required: true})}${field('T2', '3267.80', 'number')}${field('T3', '0', 'number')}<div class="wide">${B('Завершить редактирование устройства', 'modal:device-lock')}</div>`), {kind: 'dialog'});
